class_name LifecyclePredict1
extends RefCounted

func run() -> int:
	var item := Node.new()
	var is_valid_before := is_instance_valid(item)
	item.free()
	var is_valid_after := is_instance_valid(item)
	var count := 0
	if is_valid_before:
		count += 10
	if is_valid_after:
		count += 5
	return count

