class_name LifecyclePredict4
extends RefCounted

func run() -> int:
	var root := Node.new()
	var child := Node.new()
	root.add_child(child)

	var was_child_valid := is_instance_valid(child)
	root.free()
	var is_child_valid_now := is_instance_valid(child)

	if was_child_valid and not is_child_valid_now:
		return 100
	return 0
